from taf.internal.gnb.oam.rap.client.rap.v2 import AUTHApi, ApiClient, Configuration, TokenResponseBody
from taf.internal.gnb.oam.rap.client.rap.v2.rest import ApiException
from urllib3.util.retry import MaxRetryError
from taf.sbts.oam.sc.rest.exception import AuthenticationFailed, IncorrectLoginCredentials
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SecV1(object):
    def __init__(self, con_details):
        self.configuration = self._create_configuration_prepare(con_details)
        self.auth_api_instance = AUTHApi(ApiClient(self.configuration))
        self.refresh_token = None
        self.username = None
        self.password = None

    @staticmethod
    def _create_configuration_prepare(con_details):
        config_object = Configuration()
        config_object.host = con_details.make_configuration_host(original_endpoint=config_object.host)
        config_object.retries = 0
        config_object.verify_ssl = con_details.secure
        return config_object

    def login(self, username, password, scope="write"):
        self.username = username
        self.password = password
        try:
            token_response = self.auth_api_instance.auth_token_post(grant_type="password", username=username,
                                                                    password=password, scope=scope)
        except (ApiException, MaxRetryError) as e:
            raise AuthenticationFailed('Authentication failed. {}'.format(e))
        else:
            if not isinstance(token_response, TokenResponseBody):
                exception_message = 'Incorrect username/password combination!'
                raise IncorrectLoginCredentials(exception_message)

        self.configuration.access_token = token_response.access_token
        self.configuration.api_key_prefix['key'] = 'OAuth2'
        self.configuration.api_key['key'] = token_response.access_token
        self.refresh_token = token_response.refresh_token
        logger.info("Login successfully")
        logger.debug("Login Response:\n{}".format(token_response))
        if token_response.scope != scope:
            logging.warning("[ASIR WebEM] Granted scope different than requested!\n"
                            "Requested: [{}]\n"
                            "Granted: [{}]".format(scope, token_response.scope))
            if scope == 'write':
                logging.warning("[ASIR WebEM] All operations which require 'write' rights will not be possible\n"
                                "ASiR allows only one session with 'write' rights. "
                                "Please logout from all established sessions")
        return self.configuration.access_token

    def refresh(self, scope="write"):
        logger.debug("Refresh token")
        try:
            token_response = self.auth_api_instance.auth_token_post(grant_type="refresh_token",
                                                                    username=self.username,
                                                                    password=self.password,
                                                                    refresh_token=self.refresh_token,
                                                                    scope=scope)
        except (ApiException, MaxRetryError) as e:
            raise AuthenticationFailed('Authentication failed. {}'.format(e))
        else:
            if not isinstance(token_response, TokenResponseBody):
                exception_message = 'Incorrect username/password combination!'
                raise IncorrectLoginCredentials(exception_message)

        self.configuration.access_token = token_response.access_token
        self.configuration.api_key_prefix['key'] = 'OAuth2'
        self.configuration.api_key['key'] = token_response.access_token
        self.refresh_token = token_response.refresh_token
        logger.debug("Refresh successfully")
        logger.debug("Refresh Response:\n{}".format(token_response))
        return self.configuration.access_token

    def logout(self, token_type_hint="access_token"):
        self.auth_api_instance.auth_revoke_post(self.configuration.access_token, token_type_hint=token_type_hint)

    def get_number_of_logged_in_users(self, count=0):
        return self.auth_api_instance.auth_users_get(x_nokia_autologout_timer='restart', count=count)
